const o = $input.first().json.output;
const zone = 'America/Sao_Paulo';
const today = DateTime.now().setZone(zone).startOf('day');

let start = null, end = null, label = 'em todo o período';
switch (o.period) {
  case 'today': start = end = today; label = 'hoje'; break;
  case 'yesterday': start = end = today.minus({ days: 1 }); label = 'ontem'; break;
  case 'this_week': start = today.startOf('week'); end = start.plus({ days: 6 }); label = 'nesta semana'; break;
  case 'last_week': start = today.minus({ weeks: 1 }).startOf('week'); end = start.plus({ days: 6 }); label = 'na semana passada'; break;
  case 'this_month': start = today.startOf('month'); end = today.endOf('month').startOf('day'); label = 'neste mês'; break;
  case 'last_month': start = today.minus({ months: 1 }).startOf('month'); end = start.endOf('month').startOf('day'); label = 'no mês passado'; break;
  case 'last_n_days': {
    const n = o.n_days ?? 7;
    start = today.minus({ days: n - 1 }); end = today; label = `nos últimos ${n} dias`; break;
  }
  case 'this_year': start = today.startOf('year'); end = today.endOf('year').startOf('day'); label = 'neste ano'; break;
  case 'explicit_range': {
    const s = o.start_date ? DateTime.fromISO(o.start_date, { zone }) : null;
    const e = o.end_date ? DateTime.fromISO(o.end_date, { zone }) : s;
    if (s?.isValid) {
      start = s; end = e?.isValid ? e : s;
      label = `de ${s.toFormat('dd/MM/yyyy')} a ${end.toFormat('dd/MM/yyyy')}`;
    }
    break;
  }
}

return [{
  json: {
    user_id: $('Resolve Conversation').first().json.user_id,
    start_date: start ? start.toISODate() : null,
    end_date: end ? end.toISODate() : null,
