  }
}];

const items = $input.all().map(item => item.json);

return [{
  json: {
    categories: items
  }
}];

let payload = $input.first().json.payload ?? {};
if (typeof payload === 'string') payload = JSON.parse(payload);

let next_step;
if (payload.amount === null || payload.amount === undefined) next_step = 'awaiting_amount';
else if (!payload.category_id) next_step = 'awaiting_category';
else if (payload.description === undefined || payload.description === null) next_step = 'awaiting_description';
  else if (!payload.expense_date) next_step = 'awaiting_date';
else next_step = 'confirmation';

return [{ json: { next_step, payload } }];

const conversation = $input.first().json;
const userId = Number($('Resolve Conversation').first().json.user_id);

let payload = conversation.payload ?? {};

if (typeof payload === "string") {
  payload = JSON.parse(payload);
}

const page = Math.max(1, Number(payload.page) || 1);
const PAGE_SIZE = 8;
const filters = payload.filters ?? {};

if (!Number.isSafeInteger(userId) || userId <= 0) {
  throw new Error("ID do usuário inválido.");
}

const conditions = [`e.user_id = ${userId}`];

// Categorias: qualquer ID selecionado
const categoryIds = [
  ...new Set(
    (Array.isArray(filters.category_id)
      ? filters.category_id
      : filters.category_id != null
        ? [filters.category_id]
        : []
    )
      .map(Number)
      .filter(id => Number.isSafeInteger(id) && id > 0)
  ),
];

if (categoryIds.length > 0) {
  conditions.push(`e.category_id IN (${categoryIds.join(", ")})`);
}

// Período
if (filters.start_date) {
  const date = String(filters.start_date);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new Error("Data inicial inválida.");
  }

  conditions.push(`e.expense_date >= '${date}'::date`);
}

if (filters.end_date) {
  const date = String(filters.end_date);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    throw new Error("Data final inválida.");
  }

  conditions.push(`e.expense_date < '${date}'::date`);
}

// Valores
for (const [key, operator] of [
  ["min_amount", ">="],
  ["max_amount", "<="],
]) {
  if (filters[key] != null && filters[key] !== "") {
    const amount = Number(filters[key]);

    if (!Number.isFinite(amount)) {
      throw new Error(`Valor inválido para ${key}.`);
    }

    conditions.push(`e.amount ${operator} ${amount}`);
  }
}

// Descrição: qualquer termo correspondente
const descriptions = (
  Array.isArray(filters.description)
    ? filters.description
    : filters.description
      ? [filters.description]
      : []
)
  .map(value => String(value).trim())
  .filter(Boolean);

if (descriptions.length > 0) {
  const descriptionConditions = descriptions.map(value => {
    const escaped = value
      .replace(/\\/g, "\\\\")
      .replace(/'/g, "''")
      .replace(/%/g, "\\%")
      .replace(/_/g, "\\_");

    return `e.description ILIKE '%${escaped}%' ESCAPE E'\\\\'`;
  });

  conditions.push(`(${descriptionConditions.join(" OR ")})`);
}

return [{
  json: {
    page,
    page_size: PAGE_SIZE,
    offset: (page - 1) * PAGE_SIZE,
    whereClause: conditions.join(" AND "),
    activeFilters: filters,
  },
}];

