  .all()
  .map((item) => item.json)
  .filter((item) => item.id !== undefined);

const base = $("Build Expense Query").first().json;

const page = Number(base.page);
const pageSize = Number(base.page_size);

const hasNext = rows.length > pageSize;
const hasPrevious = page > 1;

const expenses = rows.slice(0, pageSize);

const lines = expenses.map((expense) => {
  const date = new Date(expense.expense_date).toLocaleDateString("pt-BR", {
    timeZone: "UTC",
  });

  const description = String(expense.description ?? "").trim();

  const suffix = description ? ` - ${description}` : "";

  return `${date} - ${expense.category_name} - R$ ${Number(expense.amount).toFixed(2)}${suffix}`;
});

const navigation = [];

if (hasPrevious) {
  navigation.push({
    text: "◀",
    callback_data: `list_page:${page - 1}`,
  });
}

if (hasNext) {
  navigation.push({
    text: "▶",
    callback_data: `list_page:${page + 1}`,
  });
}

const activeFilters = base.activeFilters ?? {};

const hasFilters = Object.values(activeFilters).some((value) => {
  if (Array.isArray(value)) {
    return value.length > 0;
  }

  return value !== null && value !== undefined && value !== "";
});

const actions = [
  {
    text: "Filtrar",
    callback_data: "list_filter",
  },
];

if (hasFilters) {
  actions.push({
    text: "Limpar filtro",
    callback_data: "clear_filter",
  });
}

actions.push({
  text: "Fechar",
  callback_data: "list_close",
});

return [
  {
    json: {
      chat_id: $("Normalize Input").first().json.chat_id,
